using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class LeoTolstoy
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The hero of my tale, whom I love with all the power of my soul, whom I have tried to portray in all his beauty, who has been, is, and will be beautiful, is Truth.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Never did Christ utter a single word attesting to a personal resurrection and a life beyond the grave.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Error is the force that welds men together; truth is communicated to men only by deeds of truth. Only deeds of truth, by introducing light into the conscience of each individual, can dissolve the cohesion of error, and detach men one by one from the mass united together by the cohesion of error.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "I know that my unity with all people cannot be destroyed by national boundaries and government orders.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "A man can live and be healthy without killing animals for food; therefore, if he eats meat, he participates in taking animal life merely for the sake of his appetite. And to act so is immoral.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "I sit on a man's back, choking him, and making him carry me, and yet assure myself and others that I am very sorry for him and wish to ease his lot by any means possible, except getting off his back.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Six feet of land was all that he needed.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The happiness of men consists in life. And life is in labor.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The vocation of every man and woman is to serve other people.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The more is given the less the people will work for themselves, and the less they work the more their poverty will increase.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Condemn me if you choose — I do that myself, — but condemn me, and not the path which I am following, and which I point out to those who ask me where, in my opinion, the path is.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "In all history there is no war which was not hatched by the governments, the governments alone, independent of the interests of the people, to whom war is always pernicious even when successful.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Government is violence, Christianity is meekness, non-resistance, love. And, therefore, government cannot be CHRISTIAN, and a man who wishes to be a Christian must not serve government.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Tell people that war is an evil, and they will laugh; for who does not know it? Tell them that patriotism is an evil, and most of them will agree, but with a reservation. 'Yes,' they will say, 'wrong patriotism is an evil; but there is another kind, the kind we hold.' But just what this good patriotism is, no one explains.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Understand that all the evils from which you suffer, you yourselves cause by yielding to the suggestions by which emperors, kings, members of parliament, governors, officers, capitalists, priests, authors, artists, and all who need this fraud of patriotism in order to live upon your labour, deceive you!", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "If people would but understand that they are not the sons of some fatherland or other, nor of Governments, but are sons of God, and can therefore neither be slaves nor enemies one to another - those insane, unnecessary, worn-out, pernicious organizations called Governments, and all the sufferings, violations, humiliations and crimes which they occasion, would cease.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The workmen's revolution, with the terrors of destruction and murder, not only threatens us, but we have already been living upon its verge during the last thirty years, and it is only by various cunning devices that we have been postponing the crisis... The hatred and contempt of the oppressed people are increasing, and the physical and moral strength of the richer classes are decreasing: the deceit which supports all this is wearing out, and the rich classes have nothing wherewith to comfort themselves.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The Anarchists are right in everything; in the negation of the existing order, and in the assertion that, without authority, there could not be worse violence than that of authority under existing conditions. They are mistaken only in thinking that Anarchy can be instituted by a revolution. 'To establish Anarchy.' 'Anarchy will be instituted.' But it will be instituted only by there being more and more people who do not require protection from governmental power, and by there being more and more people who will be ashamed of applying this power.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "There can be only one permanent revolution — a moral one; the regeneration of the inner man. How is this revolution to take place? Nobody knows how it will take place in humanity, but every man feels it clearly in himself. And yet in our world everybody thinks of changing humanity, and nobody thinks of changing himself.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Everyone thinks of changing the world, but no one thinks of changing himself.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Every one who has a heart and eyes sees that you, working men, are obliged to pass your lives in want and in hard labor, which is useless to you, while other men, who do not work, enjoy the fruits of your labor—that you are the slaves of these men, and that this ought not to exist.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Not only does the action of Governments not deter men from crimes; on the contrary, it increases crime by always disturbing and lowering the moral standard of society. Nor can this be otherwise, since always and everywhere a Government, by its very nature, must put in the place of the highest, eternal, religious law (not written in books but in the hearts of men, and binding on every one) its own unjust, man-made laws, the object of which is neither justice nor the common good of all but various considerations of home and foreign expediency.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "One might think that it must be quite clear to people not deprived of reason, that violence breeds violence; that the only means of deliverance from violence lies in not taking part in it. This method, one would think, is quite obvious. It is evident that a great majority of men can be enslaved by a small minority only if the enslaved themselves take part in their own enslavement. If people are enslaved, it is only because they either fight violence with violence or participate in violence for their own personal profit. Those who neither struggle against violence nor take part in it can no more be enslaved than water can be cut. They can be robbed, prevented from moving about, wounded or killed, but they cannot be enslaved: that is, made to act against their own reasonable will.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "All violence consists in some people forcing others, under threat of suffering or death, to do what they do not want to do.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Understand then all of you, especially the young, that to want to impose an imaginary state of government on others by violence is not only a vulgar superstition, but even a criminal work. Understand that this work, far from assuring the well-being of humanity is only a lie, a more or less unconscious hypocrisy, camouflaging the lowest passions we possess.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "God is the infinite All. Man is only a finite manifestation of Him.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "God alone exists truly. Man manifests Him in time, space and matter. The more God's manifestation in man (life) unites with the manifestations (lives) of other beings, the more man exists. This union with the lives of other beings is accomplished through love. God is not love, but the more there is of love, the more man manifests God, and the more he truly exists... We acknowledge God only when we are conscious of His manifestation in us.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "How good is it to remember one's insignificance: that of a man among billions of men, of an animal amid billions of animals; and one's abode, the earth, a little grain of sand in comparison with Sirius and others, and one's life span in comparison with billions on billions of ages. There is only one significance, you are a worker. The assignment is inscribed in your reason and heart and expressed clearly and comprehensibly by the best among the beings similar to you. The reward for doing the assignment is immediately within you. But what the significance of the assignment is or of its completion, that you are not given to know, nor do you need to know it. It is good enough as it is. What else could you desire?", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Progress consists only in the greater clarification of answers to the basic questions of life. The truth is always accessible to a man. It can't be otherwise, because a man's soul is a divine spark, the truth itself. It's only a matter of removing from this divine spark (the truth) everything that obscures it. Progress consists, not in the increase of truth, but in freeing it from its wrappings. The truth is obtained like gold, not by letting it grow bigger, but by washing off from it everything that isn't gold.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The truth is that the State is a conspiracy designed not only to exploit, but above all to corrupt its citizens ... Henceforth, I shall never serve any government anywhere.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Science is meaningless because it gives no answer to our question, the only question important for us: 'what shall we do and how shall we live'", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "There is only one enduring happiness in life—to live for others.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "I have lived through much, and now I think I have found what is needed for happiness. A quiet secluded life in the country, with the possibility of being useful to people to whom it is easy to do good, and who are not accustomed to have it done to them; then work which one hopes may be of some use; then rest, nature, books, music, love for one's neighbor -- such is my idea of happiness. And then, on the top of all that, you for a mate, and children perhaps -- what more can the heart of man desire?", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Seize the moments of happiness, love and be loved! That is the only reality in the world, all else is folly. It is the one thing we are interested in here.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "You will die — and it will all be over. You will die and find out everything — or cease asking.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The only thing that we know is that we know nothing — and that is the highest flight of human wisdom.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Every action of theirs, that seems to them an act of their own free will, is in an historical sense not free at all, but in bondage to the whole course of previous history, and predestined from all eternity.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "A king is history's slave.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "A Frenchman is self-assured because he regards himself personally, both in mind and body, as irresistibly attractive to men and women. An Englishman is self-assured, as being a citizen of the best-organized state in the world, and therefore as an Englishman always knows what he should do and knows that all he does as an Englishman is undoubtedly correct. An Italian is self-assured because he is excitable and easily forgets himself and other people. A Russian is self-assured just because he knows nothing and does not want to know anything, since he does not believe that anything can be known. The German's self-assurance is worst of all, stronger and more repulsive than any other, because he imagines that he knows the truth — science — which he himself has invented but which is for him the absolute truth.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Everything comes in time to him who knows how to wait.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The strongest of all warriors are these two — Time and Patience.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "War is not a courtesy but the most horrible thing in life; and we ought to understand that, and not play at war. We ought to accept this terrible necessity sternly and seriously. It all lies in that: get rid of falsehood and let war be war and not a game. As it is now, war is the favourite pastime of the idle and frivolous.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Love hinders death. Love is life. All, everything that I understand, I understand only because I love. Everything is, everything exists, only because I love. Everything is united by it alone. Love is God, and to die means that I, a particle of love, shall return to the general and eternal source.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "To love life is to love God. Harder and more blessed than all else is to love this life in one's sufferings, in undeserved sufferings.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "For us, with the rule of right and wrong given us by Christ, there is nothing for which we have no standard. And there is no greatness where there is not simplicity, goodness, and truth.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Pure and complete sorrow is as impossible as pure and complete joy.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "History is the life of nations and of humanity. To seize and put into words, to describe directly the life of humanity or even of a single nation, appears impossible.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "All happy families resemble one another, each unhappy family is unhappy in its own way.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "He stepped down, trying not to look long at her, as if she were the sun, yet he saw her, like the sun, even without looking.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "\"Respect was invented to cover the empty place where love should be.\"", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Reason has discovered the struggle for existence and the law that I must throttle all those who hinder the satisfaction of my desires. That is the deduction reason makes. But the law of loving others could not be discovered by reason, because it is unreasonable.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "There is one evident, indubitable manifestation of the Divinity, and that is the laws of right which are made known to the world through Revelation.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "My reason will still not understand why I pray, but I shall still pray, and my life, my whole life, independently of anything that may happen to me, is every moment of it no longer meaningless as it was before, but has an unquestionable meaning of goodness with which I have the power to invest it.'", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Learn 'What dwells in man, What is not given to man', and 'What men live by'. When thou hast learnt these things, thou shalt return to heaven.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "I looked up, and did not recognize the same man: before, I had seen death in his face; but now he was alive, and I recognized in him the presence of God.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "And I understood that in man dwells Love! I was glad that God had already begun to show me what He had promised, and I smiled for the first time.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "It is not given to man to know his own needs.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "And the angel's body was bared, and he was clothed in light so that eye could not look on him; and his voice grew louder, as though it came not from him but from heaven above. And the angel said: I have learnt that all men live not by care for themselves, but by love.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "It was not given to the mother to know what her children needed for their life. Nor was it given to the rich man to know what he himself needed. Nor is it given to any man to know whether, when evening comes, he will need boots for his body or slippers for his corpse.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "I knew before that God gave life to men and desires that they should live; now I understood more than that. I understood that God does not wish men to live apart, and therefore he does not reveal to them what each one needs for himself; but he wishes them to live united, and therefore reveals to each of them what is necessary for all.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "I have now understood that though it seems to men that they live by care for themselves, in truth it is love alone by which they live. He who has love, is in God, and God is in him, for God is love.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "Quite often a man goes on for years imagining that the religious teaching that had been imparted to him since childhood is still intact, while all the time there is not a trace of it left in him.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "I cannot recall those years without horror, loathing, and heart-rending pain. I killed people in war, challenged men to duels with the purpose of killing them, and lost at cards; I squandered the fruits of the peasants' toil and then had them executed; I was a fornicator and a cheat. Lying, stealing, promiscuity of every kind, drunkenness, violence, murder — there was not a crime I did not commit... Thus I lived for ten years.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "One can only live while one is intoxicated with life; as soon as one is sober it is impossible not to see that it is all a mere fraud and a stupid fraud!", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "It is possible to live only as long as life intoxicates us; once we are sober we cannot help seeing that it is all a delusion, a stupid delusion.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "The only absolute knowledge attainable by man is that life is meaningless.", Author = "Leo Tolstoy" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leo_Tolstoy", Text = "For man to be able to live he must either not see the infinite, or have such an explanation of the meaning of life as will connect the finite with the infinite.", Author = "Leo Tolstoy" },
        };
    }
}